"""Pan centering from actual selected-track measurements, with latched stops.

Pulse units are microseconds, not measured shaft degrees. A fixed camera needs
measured pointing anchors; error integration is only for an axis-mounted camera.
No transport opening, FPGA loading, calibration adoption, or ARM happens here.
"""
from dataclasses import dataclass
import math
from common.motion_observation import MAX_AGE_MS, ObservationError, integer, number, validate
from .vsrv_driver import PhysicalReference, VSRVDriver


@dataclass(frozen=True)
class FollowConfig:
    rate_us_s: float = 40.0
    step_us: int = 4
    max_offset_us: int = 40
    filter_tau_ms: float = 100.0
    deadband_enter: float = .05
    deadband_exit: float = .025
    confirm_frames: int = 5
    min_score: float = .5
    min_box_width: float = 20.0
    submit_margin_ms: float = 20.0

    def __post_init__(self):
        if (not number(self.rate_us_s) or not 0 < self.rate_us_s <= 40
                or type(self.step_us) is not int or not 1 <= self.step_us <= 4
                or type(self.max_offset_us) is not int or not 1 <= self.max_offset_us <= 40
                or not number(self.filter_tau_ms) or not 0 < self.filter_tau_ms <= 1000
                or not number(self.deadband_exit) or not number(self.deadband_enter)
                or not 0 <= self.deadband_exit < self.deadband_enter <= .25
                or type(self.confirm_frames) is not int or not 2 <= self.confirm_frames <= 20
                or not number(self.min_score) or not .1 <= self.min_score <= 1
                or not number(self.min_box_width) or not 1 <= self.min_box_width <= 320
                or not number(self.submit_margin_ms) or not 1 <= self.submit_margin_ms <= 50):
            raise ValueError('Invalid bounded pan configuration')


@dataclass(frozen=True)
class FixedCameraAnchors:
    """Measured left / centre / right pulse anchors in normalized image x."""
    boot_id: str
    camera_epoch: str
    setup_id: str
    reference_us: int
    polarity: int
    left_x: float
    left_us: int
    right_x: float
    right_us: int
    evidence: str
    verified: bool

    def __post_init__(self):
        if (not all(isinstance(x, str) and x for x in
                    (self.boot_id, self.camera_epoch, self.setup_id, self.evidence))
                or self.verified is not True or type(self.polarity) is not int or self.polarity not in (-1, 1)
                or any(type(x) is not int or not 1400 <= x <= 1600
                       for x in (self.reference_us, self.left_us, self.right_us))
                or not number(self.left_x) or not number(self.right_x)
                or not -1 <= self.left_x < 0 < self.right_x <= 1
                or self.polarity*(self.left_us-self.reference_us) >= 0
                or self.polarity*(self.right_us-self.reference_us) <= 0):
            raise ValueError('Verified fixed-camera pointing anchors required')

    def pulse(self, error):
        if error < 0:
            return self.reference_us+(self.left_us-self.reference_us)*min(1., error/self.left_x)
        return self.reference_us+(self.right_us-self.reference_us)*min(1., error/self.right_x)


class ShadowDriver:
    """No IO; acknowledgements describe software commands, never hardware."""
    def __init__(self):
        self.submissions = []
        self.stops = 0

    def submit(self, pulse, source_time, freshness_s, margin_s):
        self.submissions.append((pulse, source_time))
        return {'outcome': 'ACCEPTED', 'scope': 'SOFTWARE_SHADOW'}

    def stop(self):
        self.stops += 1


class PanFollowController:
    def __init__(self, driver, boot_id, *, reference_us=1500, polarity=-1,
                 camera_moves_with_axis=True, anchors=None, config=None, physical=False):
        if (not isinstance(boot_id, str) or not boot_id or type(reference_us) is not int
                or not 1400 <= reference_us <= 1600 or type(polarity) is not int or polarity not in (-1, 1)
                or type(camera_moves_with_axis) is not bool or type(physical) is not bool):
            raise ValueError('Explicit pan setup required')
        if physical:
            ref = getattr(driver, 'reference', None)
            if (not isinstance(driver, VSRVDriver) or not isinstance(ref, PhysicalReference)
                    or (driver.boot_id, ref.boot_id, ref.reference_us, ref.polarity, ref.camera_moves_with_axis)
                    != (boot_id, boot_id, reference_us, polarity, camera_moves_with_axis)):
                raise ValueError('Already-armed verified VSRV driver and matching physical reference required')
        elif not isinstance(driver, ShadowDriver):
            raise ValueError('Shadow mode only accepts the no-IO shadow driver')
        if camera_moves_with_axis:
            if anchors is not None:
                raise ValueError('Fixed-camera mapping cannot control an axis-mounted camera')
        elif (not isinstance(anchors, FixedCameraAnchors)
              or (anchors.boot_id, anchors.reference_us, anchors.polarity) != (boot_id, reference_us, polarity)):
            raise ValueError('A stationary camera requires measured anchors, never integrated image error')
        if physical and anchors is not None and anchors.setup_id != driver.reference.setup_id:
            raise ValueError('Anchor setup does not match physical reference')
        self.driver, self.boot, self.physical = driver, boot_id, physical
        self.reference, self.polarity, self.anchors = reference_us, polarity, anchors
        self.config = config or FollowConfig()
        self.low = max(1400, reference_us-self.config.max_offset_us)
        self.high = min(1600, reference_us+self.config.max_offset_us)
        self.context = self.target = self.last_source = self.last_payload = None
        self.last_now = self.filtered = None
        self.warmup = self.accepted = 0
        self.engaged = False
        self.position = float(reference_us)
        self.pulse_us = reference_us
        self.stopped = False
        self.reason = 'WAITING_FOR_TARGET'
        self.stop_confirmed = None
        self.last_result = None

    def status(self):
        return {'state': 'DISARMED' if self.stopped else 'FOLLOWING' if self.accepted else 'WAITING',
                'reason': self.reason, 'scope': 'PHYSICAL_VSRV' if self.physical else 'SOFTWARE_SHADOW',
                'physical_actuation': self.physical, 'accepted_commands': self.accepted,
                'target': self.target, 'warmup_frames': self.warmup,
                'pulse_us': self.pulse_us, 'pulse_limits_us': [self.low, self.high],
                'filtered_error': self.filtered, 'source_mono_ms': None if self.last_source is None else self.last_source[1],
                'stop_confirmed': self.stop_confirmed, 'mechanical_angle_measured': False}

    def stop(self, reason='STOP'):
        self.stopped, self.reason = True, reason
        try:
            self.driver.stop()
            self.stop_confirmed = True
        except Exception:
            self.stop_confirmed = False
            raise
        return self.status()

    def poll(self, now_ms):
        if self.stopped:
            return self.status()
        if not integer(now_ms) or self.last_now is not None and now_ms < self.last_now:
            return self.stop('INVALID_CLOCK')
        self.last_now = now_ms
        if self.last_source is not None and now_ms-self.last_source[1] >= MAX_AGE_MS:
            return self.stop('SOURCE_EXPIRED')
        return self.status()

    def observe(self, value, now_ms, *, allow_fixture=False):
        self.poll(now_ms)
        if self.stopped:
            return self.status()
        try:
            packet = validate(value, self.boot, now_ms, allow_fixture=allow_fixture and not self.physical)
        except ObservationError as exc:
            if self.context is None and str(exc) in ('SOURCE_NO_TARGET', 'SOURCE_EXPIRED'):
                self.reason = str(exc)
                return self.status()
            return self.stop(str(exc))
        context = (packet['service_epoch'], packet['camera_epoch'], packet['frame_width'], packet['frame_height'])
        target = packet['target']
        key = (target['track_id'], target['track_generation'])
        if self.context is not None and context != self.context:
            return self.stop('CAMERA_CONTEXT_CHANGED')
        if self.target is not None and key != self.target:
            return self.stop('TARGET_CHANGED')
        if self.anchors is not None and packet['camera_epoch'] != self.anchors.camera_epoch:
            return self.stop('ANCHOR_CAMERA_CHANGED')
        source = (packet['source_frame_id'], packet['source_mono_ms'])
        payload = (context, key, tuple(target['box']), target['score'])
        if self.last_source is not None:
            if source == self.last_source:
                if payload != self.last_payload:
                    return self.stop('SOURCE_MUTATED')
                self.reason = 'NO_NEW_SOURCE'
                return self.status()
            if source[0] <= self.last_source[0] or source[1] <= self.last_source[1]:
                return self.stop('SOURCE_REORDERED')
        x, y, w, h = target['box']
        if target['score'] < self.config.min_score or w < self.config.min_box_width:
            return self.stop('TARGET_QUALITY')
        if x < 1 or x+w > packet['frame_width']-1:
            return self.stop('HORIZONTAL_BORDER')
        error = (x+w/2)/(packet['frame_width']/2)-1
        dt = None if self.last_source is None else source[1]-self.last_source[1]
        if dt is not None and not 0 < dt < MAX_AGE_MS:
            return self.stop('SOURCE_GAP')
        self.context, self.target = context, key
        self.last_source, self.last_payload = source, payload
        self.filtered = error if self.filtered is None else self.filtered+(1-math.exp(-dt/self.config.filter_tau_ms))*(error-self.filtered)
        self.warmup += 1
        if self.warmup < self.config.confirm_frames:
            self.reason = 'CONFIRMING_TARGET'
            return self.status()
        if abs(self.filtered) <= self.config.deadband_exit:
            self.engaged = False
        elif abs(self.filtered) >= self.config.deadband_enter:
            self.engaged = True
        error = self.filtered if self.engaged else 0.
        limit = min(self.config.step_us, self.config.rate_us_s*dt/1000)
        if self.anchors is not None:
            goal = self.anchors.pulse(error)
            delta = max(-limit, min(limit, goal-self.position))
        else:
            delta = max(-limit, min(limit, self.polarity*self.config.rate_us_s*error*dt/1000))
        candidate = max(self.low, min(self.high, self.position+delta))
        pulse = round(candidate)
        try:
            result = self.driver.submit(pulse, source[1]/1000., MAX_AGE_MS/1000., self.config.submit_margin_ms/1000.)
        except Exception:
            self.stop('TRANSPORT_ERROR')
            raise
        self.last_result = result
        if result.get('outcome') != 'ACCEPTED':
            return self.stop(str(result.get('reason', 'ACK_NOT_ACCEPTED')))
        self.position, self.pulse_us = candidate, pulse
        self.accepted += 1
        self.reason = 'AT_LIMIT' if pulse in (self.low, self.high) else 'CENTERED' if not self.engaged else 'FOLLOWING'
        return self.status()

"""Keep lease renewal outside GTK/audio's Python interpreter; never auto-replay."""
from collections import deque
import copy
import math
import multiprocessing
import signal
import threading
import time
import uuid


def backend(connection, config, *, transport_factory=None):
    if transport_factory is None and config.get('face_follow_config'):
        from board.motion.manual_live_config import current_config
        config=current_config(config)
    from board.motion.manual import ManualPan
    from board.motion.manual_vsrv import ManualVSRV
    shutdown = threading.Event()
    for sig in (signal.SIGTERM, signal.SIGINT):
        signal.signal(sig, lambda *unused:shutdown.set())
    pan = ManualPan(transport_factory or (lambda:ManualVSRV(config)),
        duration_s=config.get('maximum_duration_s',2.),
        minimum_us=config.get('manual_minimum_us',1400),maximum_us=config.get('manual_maximum_us',1600))
    last_status = 0
    try:
        while not shutdown.is_set():
            if connection.poll(.02):
                request = connection.recv()
                kind = request['kind']
                if kind == 'close':
                    break
                try:
                    if kind == 'stop':
                        result = pan.stop()
                    elif (type(request.get('issued')) not in (int, float)
                          or not math.isfinite(request['issued'])
                          or not 0 <= time.monotonic()-request['issued'] <= .25):
                        raise ValueError('操作已经过期，请重新点击')
                    elif kind == 'jog':
                        result = pan.jog(request['direction'], request['step_us'], source_time=request['issued'])
                    elif kind == 'reverse':
                        result = pan.reverse()
                    else:
                        raise ValueError('无效操作')
                    response = dict(kind='ack', id=request['id'], ok=True, result=result, state=pan.read())
                except Exception as exc:
                    response = dict(kind='ack', id=request['id'], ok=False, error=str(exc), state=pan.read())
                connection.send(response)
            if time.monotonic()-last_status >= .1:
                value = pan.read()
                value['history'] = value['history'][-8:]
                connection.send(dict(kind='state', value=value, at=time.monotonic()))
                last_status = time.monotonic()
    except (EOFError, BrokenPipeError, OSError):
        pass
    finally:
        pan.close()
        connection.close()


class ManualPanProcess:
    """GTK-facing intent/status proxy. No native register access in this process."""
    def __init__(self, config, *, target=backend):
        self.config, self.target = config, target
        self.lock = threading.Lock()
        self.wake = threading.Event()
        self.closed = False
        self.requests = deque()
        self.pending_id = None
        self.reconnecting = False
        self.connection = self.process = None
        self.updated = 0
        self.value = self.initial()
        self.thread = threading.Thread(target=self.work, name='aura-pan-proxy', daemon=True)
        self.thread.start()

    @staticmethod
    def initial():
        return dict(state='CONNECTING', pulse_us=None, target_us=None, left_sign=-1,
                    minimum_us=1400, maximum_us=1600, history=[],
                    mechanical_reference_calibrated=False, automatic_following=False,
                    message='正在连接转轴', error='')

    def read(self):
        with self.lock:
            value = copy.deepcopy(self.value)
            value['backend_pid'] = self.process.pid if self.process is not None else None
            if value['state'] != 'CONNECTING' and time.monotonic()-self.updated > 1:
                value.update(state='UNAVAILABLE', message='转轴状态暂不可用，请重新连接')
            return value

    def request(self, kind, *, source_time=None, **params):
        with self.lock:
            issued = time.monotonic() if source_time is None else source_time
            if kind != 'stop' and (type(issued) not in (int, float) or not math.isfinite(issued)
                                   or not 0 <= time.monotonic()-issued <= .25):
                raise ValueError('点击已经过期，请重新点击')
            if self.closed:
                raise ValueError('转轴接口已关闭')
            if kind != 'stop' and (self.value['state'] != 'READY' or self.pending_id
                                   or time.monotonic()-self.updated > .5):
                raise ValueError('请等待本次点动结束，或重新连接')
            if len(self.requests) >= 4:
                raise ValueError('操作尚未完成，请稍后再试')
            ident = uuid.uuid4().hex
            request = dict(kind=kind, id=ident, issued=issued, **params)
            if kind == 'stop':
                self.requests.clear()
                self.requests.appendleft(request)
                self.value.update(state='STOPPING', message='正在停止')
            else:
                self.requests.append(request)
                self.value.update(state='MOVING' if kind == 'jog' else 'CONFIGURING', message='正在点动' if kind == 'jog' else '正在切换方向')
            self.pending_id = ident
            self.wake.set()
            return dict(ok=True, queued=True, command_id=ident, message=self.value['message'])

    def jog(self, direction, step_us=20, *, source_time=None):
        if direction not in ('left','right') or type(step_us) is not int or step_us not in (5,20):
            raise ValueError('请选择有效方向与步长')
        return self.request('jog', source_time=source_time, direction=direction, step_us=step_us)

    def reverse(self):
        return self.request('reverse')

    def stop(self):
        return self.request('stop') if not self.closed else dict(ok=True)

    def reconnect(self):
        with self.lock:
            if self.closed or self.value['state'] in ('MOVING','STOPPING','CONFIGURING'):
                raise ValueError('停止后才能重新连接')
            self.requests.clear()
            self.pending_id = None
            self.reconnecting = True
            self.value.update(state='CONNECTING', message='正在重新核验转轴接口', error='')
            self.wake.set()
        return dict(ok=True, queued=True, message='正在重新连接，不会恢复旧动作')

    def close(self):
        with self.lock:
            self.closed = True
            self.wake.set()
        self.thread.join(timeout=4)

    def start_backend(self):
        context = multiprocessing.get_context('spawn')
        connection, child = context.Pipe()
        process = context.Process(target=self.target, args=(child,self.config), name='aura-pan-control', daemon=True)
        process.start()
        child.close()
        with self.lock:
            self.connection, self.process = connection, process
            self.updated = time.monotonic()

    def stop_backend(self):
        connection, process = self.connection, self.process
        if process is None:
            return
        try:
            connection.send(dict(kind='close'))
        except (OSError, BrokenPipeError):
            pass
        process.join(timeout=2)
        if process.is_alive():
            process.terminate()
            process.join(timeout=1)
        if process.is_alive():
            process.kill()
            process.join(timeout=1)
        connection.close()
        with self.lock:
            self.connection = self.process = None

    def work(self):
        while True:
            try:
                self.start_backend()
                self.run_connected()
            except Exception as exc:
                with self.lock:
                    self.value.update(state='FAULT', message='转轴连接已断开，请重新连接', error=str(exc))
                    self.pending_id = None
                    self.requests.clear()
                    self.updated = time.monotonic()
            finally:
                self.stop_backend()
            while True:
                with self.lock:
                    if self.closed:
                        return
                    reconnect, self.reconnecting = self.reconnecting, False
                if reconnect:
                    break
                self.wake.wait(.1)
                self.wake.clear()

    def run_connected(self):
        while True:
            with self.lock:
                if self.closed:
                    return
                reconnect, self.reconnecting = self.reconnecting, False
                request = self.requests.popleft() if self.requests else None
            if reconnect:
                self.stop_backend()
                self.start_backend()
                continue
            if request:
                self.connection.send(request)
            while self.connection.poll(0):
                response = self.connection.recv()
                with self.lock:
                    if response['kind'] == 'ack':
                        if response['id'] == self.pending_id:
                            self.value = response['state']
                            if not response['ok']:
                                self.value['message'] = response['error']
                            self.pending_id = None
                            self.updated = time.monotonic()
                    elif not self.pending_id:
                        self.value = response['value']
                        self.updated = response['at']
            if not self.process.is_alive():
                raise RuntimeError('独立转轴控制已退出，请重新连接')
            self.wake.wait(.02)
            self.wake.clear()

"""The only command writer for the framework's virtual axis."""
from common.contracts import MotionCommand


class MotionService:
    def __init__(self, guard):
        self.guard = guard
        self.target_key = None

    def update(self, evidence, now_ms):
        if evidence is None or not evidence.usable(now_ms, self.guard.clock_domain):
            self.guard.stop("NO_FRESH_TARGET")
            return {"accepted": False, "reason": "NO_FRESH_TARGET", "physical_actuation": False}
        track = evidence.track
        if self.target_key != track.target_key:
            self.target_key = track.target_key
        self.guard.select_target(track.target_key)
        axis = ((track.box[0] + track.box[2] / 2) - track.frame.width / 2) / (track.frame.width / 2)
        command = MotionCommand(self.guard.session_id, self.guard.recovery_generation,
                                self.guard.seq + 1, evidence, max(-1.0, min(1.0, axis)))
        return self.guard.submit(command, now_ms)

"""Private local readback of the pinned *actual* INT8 gallery; never writes.

Used only on the voice network worker. It loads no camera/model/native runner.
The private embeddings are validated and hashed here, never returned or stored.
"""
import hashlib,json,sqlite3
from pathlib import Path
from board.identity.store import normalize
from board.interaction.ui_contract import millis,validate_snapshot
from common.face_binding_wire import validate_packet

class FaceGalleryReadback:
    def __init__(self,config,*,verify=None,clock=millis):
        if not isinstance(config,dict) or config.get('version')!=1 or config.get('enabled') is not True:
            raise ValueError('Pinned actual face gallery readback is disabled')
        self.config=dict(config);self.verify=verify or self._verify;self.clock=clock

    @classmethod
    def configured(cls):
        path=Path(__file__).resolve().parents[3]/'config/face_gallery_readback.local.json'
        try:return cls(json.loads(path.read_text(encoding='utf-8')))
        except (OSError,ValueError,TypeError):return None

    @staticmethod
    def _verify(config):
        boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip()
        if boot!=config['board_boot_id']:raise ValueError('Readback configuration belongs to another boot')
        proc=Path('/proc')/str(config['camera_pid'])
        cmd=proc.joinpath('cmdline').read_bytes()
        ticks=proc.joinpath('stat').read_text().rsplit(')',1)[1].split()[19]
        if hashlib.sha256(cmd).hexdigest()!=config['camera_cmdline_sha256'] or ticks!=config['camera_start_ticks']:
            raise ValueError('Actual camera process owner changed')
        for name,digest in config['source_sha256'].items():
            if hashlib.sha256(Path(name).read_bytes()).hexdigest()!=digest:raise ValueError('Pinned camera source changed')
        runtime=json.loads(Path(config['camera_config']).read_text())
        if runtime.get('identity')!={'enabled':True,'config':config['identity_config']}:
            raise ValueError('Actual camera selected a different identity source')
        identity=json.loads(Path(config['identity_config']).read_text())
        if (identity.get('database')!=config['database'] or identity.get('model_id')!=config['model_id']
            or identity.get('schema_version')!='aura-camera-identity-1'
            or identity.get('result_ttl_ms')!=config['result_ttl_ms']
            or identity.get('feature_backend',{}).get('kind')!='dpu_sface'
            or identity.get('feature_backend',{}).get('model_sha256')!=config['model_sha256']):
            raise ValueError('Actual INT8 model/gallery source changed')
        if config['dimension']!=128 or config['backend']!='DPU_SFACE_INT8':raise ValueError('Unexpected pinned INT8 dimension/backend')

    def read(self,meta,snapshot):
        c=self.config;self.verify(c)
        value=validate_snapshot(snapshot,meta['board_boot_id'],self.clock())
        identity=value['modules'].get('identity',{})
        if (value['source_kind']!='actual' or value['board_boot_id']!=c['board_boot_id']
           or identity.get('backend')!=c['backend']):raise ValueError('Actual identity backend is unavailable')
        path=Path(c['database']).expanduser()
        if path.is_symlink() or not path.is_file():raise ValueError('Actual private gallery is unavailable')
        resolved=path.resolve(strict=True)
        try:db=sqlite3.connect(resolved.as_uri()+'?mode=ro',uri=True,timeout=.03)
        except sqlite3.Error as exc:raise ValueError('Private face gallery readback unavailable') from exc
        try:
            db.execute('PRAGMA query_only=ON');db.execute('PRAGMA busy_timeout=30');db.execute('BEGIN')
            binding=db.execute('SELECT model_id,dimension FROM identity_model_binding').fetchall()
            if binding!=[(c['model_id'],c['dimension'])]:raise ValueError('Wrong INT8 gallery model binding')
            foreign=db.execute('SELECT DISTINCT model_id,dimension FROM templates').fetchall()
            if any(row!=(c['model_id'],c['dimension']) for row in foreign):raise ValueError('Mixed face models in actual gallery')
            revision=db.execute("SELECT value FROM metadata WHERE key='revision'").fetchone()
            if (revision is None or type(revision[0]) is not int or revision[0]!=identity.get('db_version')):
                raise ValueError('Actual gallery revision changed during capture')
            rows=db.execute('SELECT t.identity_id,t.embedding FROM templates t JOIN identities i ON i.id=t.identity_id '
                'WHERE t.model_id=? AND t.dimension=? ORDER BY t.identity_id',(c['model_id'],c['dimension'])).fetchmany(33)
            if len(rows)>32:raise ValueError('Original face gallery limit exceeded')
            inventory=[]
            for identity_id,raw in rows:
                if not isinstance(raw,str) or len(raw)>200000:raise ValueError('Invalid private face template')
                vector=json.loads(raw)
                try:normalize(vector,c['dimension'])
                finally:vector=None
                inventory.append([identity_id,hashlib.sha256(raw.encode()).hexdigest()])
            raw=None;rows=None
            current=None
